import re


_COMPONENT = r"(?:0|[1-9][0-9]*)"
_VERSION = re.compile(rf"{_COMPONENT}\.{_COMPONENT}\.{_COMPONENT}")
_HEADER = re.compile(r"([a-z]+)(?:\([^()]+\))?(!)?: \S.*")
_BREAKING_PREFIXES = ("BREAKING CHANGE: ", "BREAKING-CHANGE: ")


def _increment(component):
    # Carry through trailing nines without limiting the number of digits.
    prefix = component.rstrip("9")
    zeros = "0" * (len(component) - len(prefix))
    if not prefix:
        return "1" + zeros
    return prefix[:-1] + str(int(prefix[-1]) + 1) + zeros


def next_version(current, commits):
    """Return the version implied by the strongest valid commit message."""
    if not isinstance(current, str) or not _VERSION.fullmatch(current):
        raise ValueError("Expected a MAJOR.MINOR.PATCH version")

    parts = current.split(".")
    bump_index = len(parts)
    for message in commits:
        lines = message.splitlines()
        header = _HEADER.fullmatch(lines[0]) if lines else None
        if not header:
            continue
        kind, breaking = header.groups()
        if breaking or any(line.startswith(_BREAKING_PREFIXES) for line in lines[1:]):
            bump_index = 1 if parts[0] == "0" else 0
            break
        if kind == "feat" and parts[0] != "0":
            bump_index = 1
        elif kind in ("feat", "fix"):
            bump_index = min(bump_index, 2)

    if bump_index == len(parts):
        return current
    parts[bump_index] = _increment(parts[bump_index])
    parts[bump_index + 1:] = ["0"] * (2 - bump_index)
    return ".".join(parts)
